import { Project } from '../../../src'
import { runTestOnFunction, validateDiagnostic } from '../../test-utils'
import { ts, path } from '@servicenow/sdk-build-core'

describe('RequestedForVariable  Diagnostic Validation', () => {
    describe('VariableSet - Duplicate RequestedForVariable', () => {
        test('should fail when VariableSet has multiple RequestedForVariable', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                VariableSet({
                    $id: Now.ID['test_varset_duplicate'],
                    title: 'Test Duplicate RequestedFor',
                    internalName: 'test_duplicate',
                    variables: {
                        //@ts-expect-error avoid import
                        requestedFor1: RequestedForVariable({
                            question: 'First Requested For',
                        }),
                        //@ts-expect-error avoid import
                        requestedFor2: RequestedForVariable({
                            question: 'Second Requested For',
                        }),
                        //@ts-expect-error avoid import
                        name: SingleLineTextVariable({
                            question: 'Name',
                        }),
                    },
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                'Only one RequestedForVariable is allowed in a VariableSet'
            )
        })
    })

    describe('CatalogItem - RequestedForVariable Conflict', () => {
        test('should fail when CatalogItem has RequestedForVariable in both direct variables and variable set', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithRequestedFor = VariableSet({
                    $id: Now.ID['test_varset_requested_for'],
                    title: 'Variable Set with RequestedFor',
                    internalName: 'test_varset_requested_for',
                    variables: {
                        //@ts-expect-error avoid import
                        requestedFor: RequestedForVariable({
                            question: 'Requested For from VariableSet',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_item_conflict'],
                    name: 'Test Conflict',
                    shortDescription: 'Test',
                    variableSets: [
                        {
                            variableSet: varSetWithRequestedFor,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        requestedForDirect: RequestedForVariable({
                            question: 'Requested For from CatalogItem',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                'RequestedForVariable cannot be used in both CatalogItem variables and attached VariableSets. Remove RequestedForVariable from either the CatalogItem variables or the attached VariableSet.'
            )
        })

        test('should fail when multiple variable sets have RequestedForVariable', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSet1 = VariableSet({
                    $id: Now.ID['test_varset1'],
                    title: 'First Variable Set',
                    internalName: 'test_varset1',
                    variables: {
                        //@ts-expect-error avoid import
                        requestedFor: RequestedForVariable({
                            question: 'Requested For 1',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                const varSet2 = VariableSet({
                    $id: Now.ID['test_varset2'],
                    title: 'Second Variable Set',
                    internalName: 'test_varset2',
                    variables: {
                        //@ts-expect-error avoid import
                        requestedForAgain: RequestedForVariable({
                            question: 'Requested For 2',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItem({
                    $id: Now.ID['test_catalog_item_multiple'],
                    name: 'Test Multiple',
                    shortDescription: 'Test',
                    variableSets: [
                        { variableSet: varSet1, order: 100 },
                        { variableSet: varSet2, order: 200 },
                    ],
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ArrayLiteralExpression,
                'RequestedForVariable cannot be used in multiple VariableSets attached to the same CatalogItem. Only one RequestedForVariable is allowed across all VariableSets.'
            )
        })
    })

    describe('RecordProducer - RequestedForVariable Conflict', () => {
        test('should fail when RecordProducer has RequestedForVariable in both direct variables and variable set', async () => {
            const project = new Project({ rootDir: path.resolve(__dirname, 'project') })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports in test function
                const varSetWithRequestedFor = VariableSet({
                    $id: Now.ID['test_varset_rp'],
                    title: 'RP Variable Set',
                    internalName: 'test_varset_rp',
                    variables: {
                        //@ts-expect-error avoid import
                        requestedFor: RequestedForVariable({
                            question: 'Requested For from VariableSet',
                        }),
                    },
                })
                //@ts-expect-error avoid imports in test function
                CatalogItemRecordProducer({
                    $id: Now.ID['test_rp_conflict'],
                    name: 'Test RP Conflict',
                    shortDescription: 'Test',
                    table: 'incident',
                    variableSets: [
                        {
                            variableSet: varSetWithRequestedFor,
                            order: 100,
                        },
                    ],
                    variables: {
                        //@ts-expect-error avoid import
                        requestedForDirect: RequestedForVariable({
                            question: 'Requested For from RecordProducer',
                        }),
                    },
                    executionPlan: '523da512c611228900811a37c97c2014',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                'RequestedForVariable cannot be used in both RecordProducer variables and attached VariableSets. Remove RequestedForVariable from either the RecordProducer variables or the attached VariableSet.'
            )
        })
    })
})
